-- Remplit l'album de cartes d'un compte Moonlight : les 1039 cartes de monstre
-- (db/import/items/item_db_card.yml, Type: Card sans SubType: Enchant), @copies chacune.
-- Genere par Claude le 2026-11-16 ; a regenerer si des cartes sont ajoutees.
--
-- 1. Mettre le compte Moonlight dans @user : soit son user_id, soit via un compte de jeu
--    (SELECT user_id FROM login WHERE userid = 'NOM_DU_COMPTE').
-- 2. Le personnage doit etre DECONNECTE : le map-server garde l'album en cache pendant la
--    session et ne relirait pas la table.
-- 3. Plafond d'une reserve : MAX_AMOUNT (30 000). Une ligne existante est remise a @copies.

SET @user   = (SELECT user_id FROM login WHERE userid = 'NOM_DU_COMPTE' LIMIT 1);
SET @copies = 10000;

ON DUPLICATE KEY UPDATE `amount` = @copies;
